INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8d57-7d13-bc0c-3d0c1a2d1d7f'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'A shop sells watches at $210 each. Jimmy buys them at a 20% discount and then sells them at a 20% profit with a 10% discount on the marked price. Find the marked price.', '$224', 'Jimmy''s cost price is 80% of 210, so it is 168. To make a 20% profit, he needs to sell at 201.60. If this is after a 10% discount, then the marked price is 201.60 ÷ 0.9 = 224.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.887Z'::timestamptz, '2026-08-15T07:36:12.887Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8d6a-75d6-b7fa-f880bb491ff9'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'A student walks 1000 metres at 4 km/h, takes a 5 minute break, then runs 1.3 km in 5 minutes. Will the whole exercise be completed by 09:30 if the student starts at 08:50?', 'Yes', 'Walking 1000 m at 4 km/h takes 15 minutes. Add the 5 minute break and 5 minutes running for a total of 25 minutes. Starting at 08:50 means the student finishes at 09:15, which is before 09:30.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.906Z'::timestamptz, '2026-08-15T07:36:12.906Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8d6f-7941-a2ab-867817a513c4'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Find the first negative term of the sequence whose nth term is 87 - 9n.', 'The 10th term (-3)', 'Solve 87 - 9n < 0. Then 9n > 87, so n > 9.666... The smallest integer n is 10. The 10th term is 87 - 90 = -3.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.911Z'::timestamptz, '2026-08-15T07:36:12.911Z'::timestamptz) ON CONFLICT (id) DO NOTHING;